INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (177, 1, 'sed -n 과 p', '5줄짜리 파일에 `sed ''p'' 파일` 을 하면 몇 줄이 출력될까요? `sed -n ''2p''`, `sed -n ''2,4p''`, `sed -n ''$p''` 는 각각 무엇을 출력할까요?', '-n 은 자동 출력을 끕니다.', NULL, NULL, '[]', 'choice', '["`sed ''p''` 는 5줄을 출력하고 `-n` 은 아무 효과가 없다", "`-n ''2p''` 는 둘째 줄을 삭제한다", "`sed ''p''` 는 자동 출력과 `p` 가 겹쳐 모든 줄이 두 번씩 나와 10줄이 된다. `-n ''2p''` 는 둘째 줄, `-n ''2,4p''` 는 2~4번째 줄, `-n ''$p''` 는 마지막 줄만 출력한다", "`$p` 는 첫 줄만 출력한다"]', 2, '`-n` 은 자동 출력을 끄는 옵션이라 `p` 와 짝으로 씁니다. `sed -n ''$=''` 는 줄 수를 출력해요.', NULL, NULL, NULL, NULL),
  (177, 2, 'sed 의 주소 지정', '`sed -n ''1~2p''`, `sed -n ''2,+1p''`, `sed -n ''/beta/,/delta/p''`, `sed -n ''2!p''` 는 각각 무엇을 출력할까요?', '줄 번호, 패턴, 범위, 부정이 섞여 있어요.', NULL, NULL, '[]', 'choice', '["`1~2p` 는 1번째와 2번째 줄이다", "`1~2p` 는 1번째부터 2줄 간격(홀수 줄), `2,+1p` 는 2번째 줄과 그 뒤 1줄, `/beta/,/delta/p` 는 `beta` 가 있는 줄부터 `delta` 가 있는 줄까지, `2!p` 는 2번째 줄을 뺀 나머지 줄이다", "`2!p` 는 2번째 줄만 출력한다", "`/beta/,/delta/p` 는 `beta` 와 `delta` 두 줄만 출력한다"]', 1, '`1~2` 는 GNU sed 의 확장 문법입니다. `3,$p` 처럼 `$` 로 마지막 줄을 가리킬 수 있어요.', NULL, NULL, NULL, NULL),
  (177, 3, 'sed 의 d 와 q', '`sed ''2d''`, `sed ''/^$/d''`, `sed ''2q''`, `sed -n ''2{p;q}''` 는 각각 무엇을 할까요?', 'd 는 지우고, q 는 끝냅니다.', NULL, NULL, '[]', 'choice', '["`2d` 는 둘째 줄을 지우고 출력하며, `/^$/d` 는 빈 줄을 모두 지우고, `2q` 는 2번째 줄까지 출력하고 종료하며, `-n ''2{p;q}''` 는 둘째 줄만 출력하고 바로 종료한다", "`2d` 는 파일에서 둘째 줄을 영구히 지운다", "`2q` 는 둘째 줄만 출력한다", "`/^$/d` 는 모든 줄을 지운다"]', 0, '`d` 는 출력에서만 줄을 지우고 파일은 그대로입니다. 큰 파일에서 앞부분만 필요할 때 `q` 로 일찍 끝내면 빨라요.', NULL, NULL, NULL, NULL),
  (177, 4, 's 명령의 플래그', '`echo ''a-a-a'' | sed ...` 에서 `s/a/X/`, `s/a/X/g`, `s/a/X/2`, `s/a/X/2g` 의 결과는 각각 무엇일까요? `I` 플래그는?', '플래그가 몇 번째를 바꿀지 정해요.', NULL, NULL, '[]', 'choice', '["`s/a/X/` 는 모두 바꿔 `X-X-X` 가 된다", "`2` 는 두 번째부터 끝까지 바꾼다", "`I` 는 첫 글자만 바꾼다", "`s/a/X/` 는 `X-a-a`(첫 번째만), `g` 는 `X-X-X`(전부), `2` 는 `a-X-a`(두 번째만), `2g` 는 `a-X-X`(두 번째부터 끝까지)이다. `I` 는 대소문자를 구분하지 않고 찾는다"]', 3, '`s/apple/X/Ig` 는 `Apple apple` 을 `X X` 로 바꿉니다.', NULL, NULL, NULL, NULL),
  (177, 5, '& 와 그룹', '`echo ''cat dog'' | sed ''s/[a-z]*/[&]/g''` 의 `&` 와, `echo ''john smith'' | sed -E ''s/(\\w+) (\\w+)/\\2, \\1/''` 의 `\\1`, `\\2` 는 각각 무엇을 뜻할까요? 확장 정규식(`-E`) 없이 괄호 그룹을 쓰려면?', '&는 찾은 문자열 전체예요.', NULL, NULL, '[]', 'choice', '["`&` 는 다음 명령을 뜻하고 그룹은 쓸 수 없다", "`-E` 없이도 `(john)` 처럼 백슬래시 없이 그룹이 된다", "`&` 는 찾은 문자열 전체(`[cat] [dog]`)이고, `\\\\1`, `\\\\2` 는 괄호로 묶은 첫째·둘째 그룹(`smith, john`)이다. `-E` 없는 기본 정규식에서는 `\\\\(john\\\\) \\\\(smith\\\\)` 처럼 괄호 앞에 백슬래시를 붙인다", "`\\\\1` 은 첫 번째 줄을 뜻한다"]', 2, '기본 정규식(BRE)에서 `+` 는 문자 그대로입니다. `aaa b` 에 `s/a+/X/` 를 하면 바뀌지 않고, `-E` 를 쓰면 `X b` 가 돼요.', NULL, NULL, NULL, NULL),
  (177, 6, '구분자 바꾸기', '경로 `/usr/bin` 의 `/usr` 을 `/opt` 로 바꿀 때 `s/\\/usr/\\/opt/` 대신 쓸 수 있는 더 읽기 쉬운 방법은?', '구분자는 슬래시가 아니어도 돼요.', NULL, NULL, '[]', 'choice', '["슬래시만 구분자로 쓸 수 있다", "`s#/usr#/opt#` 처럼 `s` 뒤의 첫 글자를 구분자로 쓰므로 `#` 같은 다른 글자로 바꾸면 슬래시를 이스케이프하지 않아도 된다 (결과는 `/opt/bin`)", "`#` 은 주석이라 쓸 수 없다", "구분자를 바꾸면 결과가 달라진다"]', 1, '경로나 URL 처럼 슬래시가 많은 문자열을 바꿀 때 편합니다.', NULL, NULL, NULL, NULL),
  (177, 7, 'sed -i', '`sed -i ''s/alpha/ALPHA/'' 파일` 과 `sed -i.bak ...`, 그리고 `sed ''s/alpha/ALPHA/'' 파일 > 파일` 은 각각 어떻게 동작할까요?', '-i 는 파일을 직접 고쳐요.', NULL, NULL, '[]', 'choice', '["`-i` 는 파일 자체를 수정하고, `-i.bak` 은 원본을 `파일.bak` 으로 남기며 수정한다. `sed ... 파일 > 파일` 은 셸이 먼저 파일을 비워 버려 파일이 0바이트가 된다", "`-i` 없이도 파일이 수정된다", "`> 파일` 로 같은 파일에 쓰면 정상적으로 수정된다", "`-i.bak` 은 백업 없이 수정한다"]', 0, '`-i` 없는 `sed` 는 결과를 화면으로만 출력하고 파일은 바꾸지 않습니다. 중요한 파일은 먼저 출력으로 확인하세요.', NULL, NULL, NULL, NULL),
  (177, 8, '여러 파일과 -s', '`sed -n ''1p'' f.txt s.txt` 와 `sed -s -n ''1p'' f.txt s.txt` 는 각각 무엇을 출력할까요?', '하나의 흐름으로 보느냐, 파일별로 보느냐예요.', NULL, NULL, '[]', 'choice', '["둘 다 각 파일의 첫 줄을 출력한다", "둘 다 첫 파일의 첫 줄만 출력한다", "`-s` 는 오류를 숨기는 옵션이다", "`-s` 없이는 두 파일을 이어 하나의 스트림으로 처리해 첫 파일의 첫 줄만 출력하고, `-s` 를 주면 파일마다 따로 처리해 각 파일의 첫 줄을 출력한다"]', 3, '`awk` 는 `FNR` 이 파일마다 1부터 다시 세어 파일별 처리가 쉽습니다.', NULL, NULL, NULL, NULL),
  (177, 9, 'a, i, c 명령', '`sed ''2i\\NEW''`, `sed ''2a\\AFTER''`, `sed ''2c\\CHANGED''` 는 각각 둘째 줄에 어떤 일을 할까요?', '삽입, 추가, 교체예요.', NULL, NULL, '[]', 'choice', '["셋 다 둘째 줄을 삭제한다", "`a` 는 둘째 줄 앞에, `i` 는 뒤에 넣는다", "`i` 는 둘째 줄 앞에 `NEW` 를 끼워 넣고, `a` 는 둘째 줄 뒤에 `AFTER` 를 덧붙이고, `c` 는 둘째 줄을 `CHANGED` 로 바꾼다", "`c` 는 둘째 줄을 복사한다"]', 2, '`-i` 옵션과 헷갈리지 마세요. 명령 `i` 는 줄 삽입이고 옵션 `-i` 는 파일 직접 수정이에요.', NULL, NULL, NULL, NULL),
  (177, 10, 'awk 의 필드와 NF', '`awk ''{print $1}''`, `awk ''{print $NF}''`, `awk ''NF>1 {print $(NF-1)}''` 는 각각 무엇을 출력할까요? 빈 줄의 `NF` 는?', 'NF 는 필드 개수예요.', NULL, NULL, '[]', 'choice', '["`$NF` 는 필드 개수를 출력한다", "`$1` 은 첫 필드, `$NF` 는 마지막 필드, `$(NF-1)` 은 끝에서 두 번째 필드이다. 빈 줄은 `NF` 가 0 이고, 기본 구분자는 연속된 공백·탭을 하나로 본다", "빈 줄의 `NF` 는 1 이다", "기본 구분자는 공백 하나이며 공백이 두 개면 빈 필드가 생긴다"]', 1, '`awk ''NF''` 는 빈 줄이 아닌 줄만 출력합니다. `a  b` 처럼 공백이 여러 개여도 `$2` 는 `b` 예요.', NULL, NULL, NULL, NULL),
  (177, 11, 'awk -F', '`awk -F, ''{print $1}''` 의 `-F,` 는 무엇일까요? `-F''[ ]''` 는 기본 구분자와 어떻게 다를까요?', '구분 문자를 정해요.', NULL, NULL, '[]', 'choice', '["`-F,` 는 쉼표를 필드 구분자로 정한다. `-F''[ ]''` 는 공백 하나하나를 구분자로 보아 `a  b` 처럼 공백이 둘이면 사이에 빈 필드가 생기고(`$2` 는 빈 값), 기본 구분자는 연속된 공백을 하나로 본다", "`-F,` 는 출력 구분자를 쉼표로 정한다", "`-F''[ ]''` 는 기본 구분자와 완전히 같다", "`-F` 는 파일 이름을 정한다"]', 0, '`-F''::''` 처럼 여러 글자도 쓸 수 있고, `BEGIN{FS=":"}` 로 정해도 같아요. 출력 구분자는 `OFS` 입니다.', NULL, NULL, NULL, NULL),
  (177, 12, 'awk 의 패턴과 BEGIN·END', '`awk ''{s+=$2} END{print s}''`, `awk ''NR>1 && NR<4''`, `awk -v min=25 ''$2>min {print $1}''` 은 각각 무엇을 할까요?', '패턴은 조건, 액션은 동작이에요.', NULL, NULL, '[]', 'choice', '["`END` 블록은 첫 줄을 읽을 때 실행된다", "패턴만 쓰면 아무것도 출력하지 않는다", "`-v` 변수는 파일 이름을 뜻한다", "첫째는 둘째 필드를 모두 더해 입력이 끝난 뒤(`END`)에 출력하고, 둘째는 `NR` 이 2~3인 줄을 액션 없이 조건만으로 출력하며(기본 액션은 `print`), 셋째는 `-v` 로 셸에서 넘긴 값 25 와 비교해 둘째 필드가 더 큰 줄의 첫 필드를 출력한다"]', 3, '`BEGIN` 은 입력을 읽기 전에 한 번 실행됩니다. 평균은 `END{print s/NR}` 로 구해요.', NULL, NULL, NULL, NULL),
  (177, 13, '초기화하지 않은 변수', '`awk ''/NOPE/ {n++} END{print n}'' 파일` 은 일치하는 줄이 없을 때 무엇을 출력할까요? `print n+0` 으로 바꾸면요?', '초기화하지 않은 변수는 빈 값이면서 0 이에요.', NULL, NULL, '[]', 'choice', '["항상 0 이 출력된다", "오류로 종료된다", "일치가 없으면 `n` 이 한 번도 만들어지지 않아 빈 줄이 출력되고, `n+0` 으로 쓰면 숫자로 취급되어 `0` 이 출력된다", "`n+0` 도 빈 줄이 출력된다"]', 2, '개수를 세는 스크립트는 `END{print n+0}` 로 쓰는 습관이 안전합니다.', NULL, NULL, NULL, NULL),
  (177, 14, 'OFS 와 $1=$1', '`echo ''a   b   c'' | awk ''BEGIN{OFS=","} {print $1,$2,$3}''`, `{print $1 $2}`, `{$1=$1; print}` 와 `{print}` 의 결과는 각각 무엇일까요?', '쉼표는 OFS 로, 공백 없이 붙이면 이어져요.', NULL, NULL, '[]', 'choice', '["`print` 도 OFS 로 바꿔 출력한다", "`print $1,$2,$3` 은 OFS 로 이어 `a,b,c`, `print $1 $2` 는 아무것도 없이 붙어 `ab` 이다. `$1=$1; print` 는 필드를 다시 조립해 `a,b,c` 가 되고, 그냥 `print` 는 원래 줄 `a   b   c` 를 그대로 출력한다", "`print $1 $2` 는 OFS 로 이어 `a,b` 가 된다", "`$1=$1` 은 첫 필드를 지운다"]', 1, '공백이 여러 개인 줄을 한 칸이나 쉼표로 정리할 때 `$1=$1` 을 씁니다.', NULL, NULL, NULL, NULL),
  (177, 15, '출력을 끄는 옵션', '`sed` 의 자동 출력을 **끄는** 옵션을 채우세요.', '"no"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["n", "e", "s", "q"]', NULL, '`p` 와 함께 써서 원하는 줄만 출력합니다.', '[0]', 'sed -{0} ''2,4p'' f.txt', NULL, NULL),
  (177, 16, '줄 삭제', '둘째 줄을 출력에서 **지우는** `sed` 명령을 채우세요.', '"delete"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["d", "p", "q", "x"]', NULL, '파일은 바뀌지 않고 출력만 달라집니다.', '[0]', 'sed ''2{0}'' f.txt', NULL, NULL),
  (177, 17, '모두 바꾸기', '한 줄에서 찾은 문자열을 **모두** 바꾸는 `s` 의 플래그를 채우세요.', '"global"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["g", "a", "all", "w"]', NULL, '플래그가 없으면 줄마다 첫 번째만 바뀝니다.', '[0]', 'sed ''s/a/X/{0}''', NULL, NULL),
  (177, 18, '확장 정규식', '`sed` 에서 괄호 그룹과 `+` 를 백슬래시 없이 쓰게 하는 옵션을 채우세요.', '"extended"의 첫 글자(대문자)예요.', NULL, NULL, '[]', 'fill', '["E", "e", "x", "r"]', NULL, '`-E` 가 없으면 `+` 는 문자 그대로 취급됩니다.', '[0]', 'sed -{0} ''s/(\\w+) (\\w+)/\\2 \\1/''', NULL, NULL),
  (177, 19, '파일 직접 수정', '`sed` 가 결과를 화면이 아닌 **파일에 직접 저장**하게 하는 옵션을 채우세요.', '"in-place"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["i", "n", "e", "s"]', NULL, '`-i.bak` 처럼 뒤에 붙이면 원본을 백업합니다.', '[0]', 'sed -{0} ''s/alpha/ALPHA/'' f.txt', NULL, NULL),
  (177, 20, '필드 구분자', '`awk` 의 **필드 구분자**를 쉼표로 정하는 옵션을 채우세요.', '"field"의 첫 글자(대문자)예요.', NULL, NULL, '[]', 'fill', '["F", "f", "d", "s"]', NULL, '`BEGIN{FS=":"}` 로 정해도 같은 결과입니다.', '[0]', 'awk -{0}, ''{print $1}'' e.csv', NULL, NULL),
  (177, 21, '마지막 필드', '한 줄의 **필드 개수**를 담은 `awk` 변수를 채워 마지막 필드를 출력하세요.', '"number of fields"의 줄임이에요.', NULL, NULL, '[]', 'fill', '["NF", "NR", "FS", "FNR"]', NULL, '`NR` 은 지금까지 읽은 줄 번호입니다.', '[0]', 'awk ''{ print ${0} }''', NULL, NULL),
  (177, 22, '첫 줄 건너뛰기', 'CSV 의 **헤더(첫 줄)를 건너뛰는** 조건의 연산자를 채우세요.', '줄 번호가 1보다 커요.', NULL, NULL, '[]', 'fill', '[">", "==", "!=", "<"]', NULL, '`NR==1` 은 첫 줄만 고르는 조건입니다.', '[0]', 'awk -F, ''NR{0}1'' e.csv', NULL, NULL),
  (177, 23, '합계 구하기', '둘째 필드를 `s` 에 **더해 가는** 식의 필드를 채우세요.', '달러 기호와 숫자예요.', NULL, NULL, '[]', 'fill', '["$2", "$1", "NF", "NR"]', NULL, '`END` 블록은 모든 줄을 읽은 뒤 실행됩니다.', '[0]', 'awk ''{ s += {0} } END { print s }'' f.txt', NULL, NULL),
  (177, 24, '키별 개수 세기', '둘째 필드를 키로 **개수를 세는** 배열의 첨자를 채우세요.', '달러 기호와 숫자예요.', NULL, NULL, '[]', 'fill', '["$2", "$3", "NR", "k"]', NULL, '`| sort` 로 정렬하면 출력 순서가 고정됩니다.', '[0]', 'awk -F, ''NR>1 { c[{0}]++ } END { for (k in c) print k, c[k] }'' e.csv', NULL, NULL),
  (177, 25, '소수 자릿수 정하기', '`printf` 로 **소수 둘째 자리까지** 출력하는 형식의 자릿수를 채우세요.', '점 뒤의 숫자예요.', NULL, NULL, '[]', 'fill', '["2", "02", ".2", "f2"]', NULL, '`printf` 는 줄바꿈을 자동으로 붙이지 않습니다.', '[0]', 'awk ''{ printf "%.{0}f", $1 }''', NULL, NULL),
  (177, 26, 'sed 로 안전하게 파일 고치기', '`sed` 로 파일을 고칠 때 실수를 줄이는 순서입니다. 순서에 맞게 놓아 보세요.', '출력으로 확인 → 의도 확인 → 백업과 함께 수정 → 비교 순서예요.', NULL, NULL, '[]', 'order', '["`sed ''s/alpha/ALPHA/'' 파일` 로 파일은 그대로 두고 결과만 출력해 본다", "출력이 의도한 변경인지 확인한다", "`sed -i.bak ''s/alpha/ALPHA/'' 파일` 로 백업을 남기며 수정한다", "`diff 파일.bak 파일` 로 달라진 줄을 확인한다"]', NULL, '`sed ... 파일 > 파일` 로 같은 파일에 쓰면 파일이 비워지니 쓰지 마세요.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (177, 27, 'CSV 부서별 합계 구하기', '헤더가 있는 CSV 에서 부서(둘째 열)별 금액(셋째 열) 합계를 구하는 순서입니다. 순서에 맞게 놓아 보세요.', '구조 확인 → 헤더 제외 → 합산 → 출력 정렬 순서예요.', NULL, NULL, '[]', 'order', '["`head -2 e.csv` 로 열 구조와 헤더를 확인한다", "`awk -F, ''NR>1 ...''` 로 헤더를 건너뛰고 쉼표로 나눈다", "`s[$2]+=$3` 으로 부서별로 금액을 더하고 `END` 에서 `for (k in s)` 로 출력한다", "결과를 `| sort` 로 정렬해 순서를 고정한다"]', NULL, '`| sort` 를 붙이면 부서가 항상 같은 순서로 출력됩니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (177, 28, '로그의 가장 흔한 레벨 찾기', '로그 파일에서 첫 단어(레벨)별 개수를 세어 가장 많은 레벨을 찾는 순서입니다. 순서에 맞게 놓아 보세요.', '특정 개수 확인 → 없는 경우 확인 → 전체 집계 → 최댓값 순서예요.', NULL, NULL, '[]', 'order', '["`awk ''/ERROR/ {n++} END{print n+0}''` 로 `ERROR` 줄 수를 센다", "일치하는 줄이 없는 패턴으로 바꿔 `0` 이 출력되는지 확인한다", "`awk ''{c[$1]++} END{for (k in c) print c[k], k}''` 로 레벨별 개수를 센다", "`| sort -rn | head -1` 로 가장 많은 레벨을 고른다"]', NULL, '`n+0` 을 쓰지 않으면 일치가 없을 때 빈 줄이 출력됩니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (177, 29, 'sed 로 범위 확인하고 지우기', '`sed` 로 줄 범위를 확인한 뒤 그 범위를 지운 결과를 만드는 순서입니다. 순서에 맞게 놓아 보세요.', '전체 줄 수 → 범위 출력 → 패턴 범위 → 범위 삭제 순서예요.', NULL, NULL, '[]', 'order', '["`sed -n ''$='' 파일` 로 전체 줄 수를 확인한다", "`sed -n ''2,4p'' 파일` 로 줄 번호 범위의 내용을 확인한다", "`sed -n ''/beta/,/delta/p'' 파일` 로 패턴으로 정한 범위가 같은지 확인한다", "`sed ''2,4d'' 파일` 로 그 범위를 뺀 결과를 출력한다 (파일은 바뀌지 않는다)"]', NULL, '결과를 파일에 반영하려면 `-i` 를 쓰되 먼저 백업하세요.', '[0, 1, 2, 3]', NULL, NULL, NULL);
